Here is the root cause:
The bug was caused by an off-by-one error in the condition that checks whether the descriptor array needs to be expanded. The original condition incorrectly allowed the number of descriptors to reach the limit before triggering an expansion, leading to an overflow of the `descs` array into the container structure, which resulted in crashes during the send completion process.

Here is the patch:
 /* tx not dword sized - pad */
 int _pad_sdma_tx_descs(struct hfi1_devdata *dd, struct sdma_txreq *tx)
 {
 	int rval = 0;

-	if ((unlikely(tx->num_desc + 1 == tx->desc_limit))) {
+	if ((unlikely(tx->num_desc == tx->desc_limit))) {
 		rval = _extend_sdma_tx_descs(dd, tx);
 		if (rval) {
 			__sdma_txclean(dd, tx);
 			return rval;
 		}
 	}

 	/* finish the one just added */
 	make_tx_sdma_desc(
 		tx,
 		SDMA_MAP_NONE,
 		dd->sdma_pad_phys,
 		sizeof(u32) - (tx->packet_len & (sizeof(u32) - 1)),
 		NULL, NULL, NULL);
 	tx->num_desc++;
 	_sdma_close_tx(dd, tx);
 	return rval;
 }



